#!/usr/bin/env python3
"""生成 PowerShell 差分语料：手写用例 + 片段组合。输出 JSON 字符串数组到 argv[1]。"""
import itertools, json, sys

hand = [
    # 正常巡检
    r"Get-ChildItem C:\logs -Recurse",
    r"Get-Process | Sort-Object WS -Descending | Select-Object -First 12",
    r'''Get-Service | Where-Object { $_.Status -eq 'Running' -and $_.Name -like 'w*' } | % { "$($_.Name): $($_.Status)" }''',
    r"'--- TOP ---'; Get-ChildItem C:\ -Directory -Force -EA SilentlyContinue | ForEach-Object { $s=(Get-ChildItem $_.FullName -Recurse -Force -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum; [pscustomobject]@{D=$_.Name;GB=[math]::Round($s/1GB,1)} } | Sort-Object GB -Descending | Select-Object -First 10",
    r"Get-WinEvent -FilterHashtable @{LogName='System';Level=1,2;StartTime=(Get-Date).AddHours(-48)} -MaxEvents 15",
    r'''$p = 'C:\tmp'; if (Test-Path $p) { Get-ChildItem $p 2>$null } else { Write-Output "missing $p" }''',
    r"foreach ($f in Get-ChildItem C:\logs) { $f.Name.ToUpper() }",
    r"try { Get-Item C:\x -ErrorAction Stop } catch { Write-Output $_.Exception.Message }",
    r"try { Get-Item C:\x } catch [System.IO.IOException] { 'io' } finally { 'done' }",
    r'''Get-Item "$(whoami)" @args''',
    r"[math]::Round((Get-PSDrive C).Free/1GB, 2)",
    r"(Get-Process robocopy -EA SilentlyContinue).Count; 'FREE=' + [math]::Round((Get-PSDrive C).Free/1GB, 2)",
    r"Get-LocalUser | ForEach-Object { $_.Name+' | enabled='+$_.Enabled }",
    r"Get-CimInstance Win32_OperatingSystem | Select-Object Caption, @{n='FreeGB';e={[math]::Round($_.FreePhysicalMemory/1MB,2)}}",
    r"Get-ChildItem C:\logs -Filter *.log | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-7) } | Measure-Object",
    r"$d = [datetime]::Now.AddDays(-1); Get-EventLog System -After $d -Newest 5",
    r"Get-Item x |`n  Select-Object Name",
    r"1..5 | % { $_ * 2 }",
    r"Get-Item a,b,c -Force:$true",
    r"Get-Process -Id $PID | Select-Object -ExpandProperty Id",
    r"[string]::Join(',', (Get-ChildItem C:\x -Name))",
    r"Get-Date -Format 'yyyy-MM-dd HH:mm'",
    r"$env:COMPUTERNAME; $env:USERNAME",
    r"Get-Item x 2>&1 | Out-String",
    r"Get-Item x *>$null",
    r"Get-NetTCPConnection -State Listen | Group-Object LocalPort | Sort-Object Count",
    r"Test-Path C:\x && Get-Item C:\x || Write-Output 'none'",
    r"[pscustomobject]@{a=1;b='x'} | ConvertTo-Json",
    r"$x = @(Get-Process); $x.Count",
    r"$h = @{}; $h['a'] = 1",
    r"Get-Item ('C:\' + 'x')",
    r"Get-ChildItem | Select-Object @{Name='KB';Expression={$_.Length/1KB}}",
    r"Get-ChildItem | Sort-Object { $_.Length } -Descending",
    r"Get-ChildItem | ForEach-Object -Begin { $n=0 } -Process { $n++ } -End { $n }",
    r"Get-Item C:\x | ForEach-Object -Parallel { $_.Name } -ThrottleLimit 4",
    # 绕过与危险写法
    r"Get-ChildItem a#; Remove-Item C:\data",
    r"Get-ChildItem x # comment",
    r"$f = Get-Item C:\x.db; $f.Delete()",
    r"(Get-Item C:\x.db).Delete()",
    r"Get-ChildItem | ForEach-Object { $_.Delete() }",
    r"Get-Item C:\x.db | ForEach-Object Delete",
    r"Get-Item C:\x.db | % Delete",
    r"Get-Item C:\x.db | % -MemberName Delete",
    r"Get-Item C:\x.db | ForEach-Object -Process {} -M Delete",
    r"Get-Item C:\x.db | ForEach-Object -MemberName Delete -ArgumentList {x}",
    r"& Remove-Item x",
    r"&'Remove-Item' x",
    r"& $c x",
    r". .\profile.ps1",
    r". { Remove-Item x }",
    r"& { Remove-Item x }",
    r"Get-Item x > C:\out.txt",
    r"Get-Item x >> C:\out.txt",
    r"Get-Item x 2> C:\err.txt",
    r"cmd /c --% dir & del x",
    r"[IO.File]::Delete('C:\x')",
    r"[System.IO.File]::Delete('C:\x')",
    r"[Environment]::Exit(0)",
    r"[Environment]::SetEnvironmentVariable('x','y')",
    r"[scriptblock]'Remove-Item x'",
    r"[scriptblock]::Create('Remove-Item x').Invoke()",
    r"Get-Item x | ForEach-Object ([scriptblock]::Create('rm x'))",
    r"'Remove-Item x' -as [scriptblock]",
    r"$env:Path = 'C:\evil'; whoami",
    r"$PSDefaultParameterValues = @{}",
    r"$ExecutionContext.InvokeCommand.InvokeScript('rm x')",
    r"function f { Remove-Item x }; f",
    r"filter f { $_ }",
    r"class C {}",
    r"exit 1",
    r"'C:\a.exe' arg",
    r"Get-Item x |",
    r"Get-Item $f.'Delete'()",
    r"Get-Item $f.$m()",
    r"$f.$m()",
    r"$f.Delete.Invoke()",
    r"iex 'Remove-Item x'",
    r"Invoke-Expression $x",
    r"Get-Item [math]::Round(1.5)",
    r"Write-Output x.y(z)",
    r"Write-Output a(Get-Date)",
    r"Write-Output a$(Get-Date)",
    r"Write-Output $x.Delete()",
    r"Write-Output ($x).Delete()",
    r"Write-Output @($x).Delete()",
    r"$o.Prop = 1",
    r"$x::Foo",
    r"Get-Item x | Remove-Item",
    r"Get-Item $using:x",
    r"Get-Item $global:x",
    r"$global:x = 1",
    r"Get-Item -Path:$(Remove-Item y)",
    r"Get-Item @{a=(Remove-Item y)}",
    r'''Get-Item "a $(Remove-Item y) b"''',
    r"Get-Item 'a'b",
    r"Get-Item a'b'",
    r'''Get-Item "a""b"''',
    r"Get-Item 'a''b'",
    r"Get-Item a!b ^c %d ~e +f",
    r"Get-Item -x=1 a=b",
    r"Get-Item C:\x\..\..\Windows",
    r"Get-Item x 3>$null 4>$null",
    r"Get-Item x 2>&1 >$null",
    r"%{ $_ }",
    r"?{ $_ }",
    r"Get-Item x | foreach { $_ }",
    r"Get-Item x | foreach Delete",
    r"Get-Item x | where { $_ }",
    r"Microsoft.PowerShell.Core\ForEach-Object -MemberName Delete",
    r"if ($x -gt 5) { 'big' } elseif ($x -lt 0) { 'neg' } else { 'ok' }",
    r"if (-not (Test-Path $p)) { New-Item $p }",
    r"$x += 1",
    r"$x -replace 'a','b'",
    r"'{0:N2}' -f 1.5",
    r"$a -split ','",
    r"$a -join ','",
    r"$a -in 1,2,3",
    r"0x1F + 1KB",
    r"[int]'5' + [double]2.5",
    r"[datetime]'2026-01-01'",
    r"[version]'1.2.3'",
    r"[void](Get-Item x)",
    r"[ordered]@{a=1}",
    r"$x[0]; $x[-1]",
    r"$x[(Remove-Item y)]",
    r"!$true",
    r"Get-Item x; ; Get-Item y",
    r"Get-Item x`r`nGet-Item y",
]

heads = ["Get-ChildItem", "gci", "Write-Output", "ForEach-Object", "%", "Where-Object", r".\x.ps1", r"C:\Windows\System32\whoami.exe", "foreach"]
args = [
    r"C:\x", "'a b'", '"a $x"', '"a $(Get-Date)"', "$x", "$_.Name", "$x.y.z", "(Get-Date)", "(Get-Date).AddDays(1)",
    "(Get-Item x).Delete()", "$x.Delete()", "@{a=1;b=(Get-Date)}", "@(Get-Date)", "{Get-Date}", "{ $_.Delete() }",
    "-Force", r"-Path:C:\x", "a,b", "a#b", "'x'#c", "2>$null", "2>&1", ">$null", "> out.txt", "@args",
    "-MemberName Delete", "Delete", "!x", "a=b", "x.y(z)", "$env:Path", "[int]5", "-Process", "-Parallel {1}",
    "$(Remove-Item y)", "a$(Remove-Item y)", "$x[0]", "$x[(Remove-Item y)]", "$x::y", "${x}", "-$x", "--%",
]
tails = ["", " | Select-Object -First 1", " | % { $_.Name }", " | % Delete", "; Remove-Item y", " && Get-Date"]

combos = []
for h, a in itertools.product(heads, args):
    combos.append(f"{h} {a}")
for h, a, b in itertools.product(heads[:4], args[:20], args[20:]):
    combos.append(f"{h} {a} {b}")
for h, a, t in itertools.product(heads[:3], args, tails):
    combos.append(f"{h} {a}{t}")

seen, corpus = set(), []
for c in hand + combos:
    c = c.replace("`n", "\n").replace("`r", "\r")
    if c not in seen:
        seen.add(c)
        corpus.append(c)
json.dump(corpus, open(sys.argv[1], "w", encoding="utf-8"), ensure_ascii=False)
print(len(corpus))
